import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Nodejs","description":"Nodejs reference documentation","frontmatter":{"title":"Nodejs","description":"Nodejs reference documentation"},"headers":[],"relativePath":"knowledge/nodejs.md","filePath":"knowledge/nodejs.md","lastUpdated":1784485118000}'),s={name:"knowledge/nodejs.md"};function d(n,e,c,i,l,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="nodejs" tabindex="-1">Nodejs <a class="header-anchor" href="#nodejs" aria-label="Permalink to &quot;Nodejs&quot;">​</a></h1><h1 id="node-js-20-—-knowledge-reference" tabindex="-1">Node.js 20+ — Knowledge Reference <a class="header-anchor" href="#node-js-20-—-knowledge-reference" aria-label="Permalink to &quot;Node.js 20+ — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Reference for modern Node.js development covering event loop mechanics, streams, buffers, child processes, worker threads, module systems, package management, and core APIs. Focused on production patterns for scalable server-side applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="event-loop" tabindex="-1">Event Loop <a class="header-anchor" href="#event-loop" aria-label="Permalink to &quot;Event Loop&quot;">​</a></h3><p>Node.js runs on a single-threaded event loop with libuv. The loop phases: timers (<code>setTimeout</code>, <code>setInterval</code>), pending callbacks, idle/prepare, poll (I/O), check (<code>setImmediate</code>), close callbacks. Microtasks (Promises, <code>queueMicrotask</code>) run after each phase. Understanding the event loop prevents blocking and race conditions.</p><h3 id="streams" tabindex="-1">Streams <a class="header-anchor" href="#streams" aria-label="Permalink to &quot;Streams&quot;">​</a></h3><p>Streams process data incrementally rather than loading entire buffers. Four types: <code>Readable</code> (source), <code>Writable</code> (destination), <code>Duplex</code> (both), <code>Transform</code> (modify). Use <code>pipe()</code> for stream composition. <code>pipeline()</code> handles errors and cleanup. Backpressure prevents memory exhaustion.</p><h3 id="buffers" tabindex="-1">Buffers <a class="header-anchor" href="#buffers" aria-label="Permalink to &quot;Buffers&quot;">​</a></h3><p><code>Buffer</code> represents fixed-size memory chunks for binary data. Created from arrays, strings, or other buffers. <code>Buffer.from()</code>, <code>Buffer.alloc()</code>, <code>Buffer.allocUnsafe()</code> are constructors. Essential for file I/O, network operations, and binary protocol handling.</p><h3 id="child-process" tabindex="-1">Child Process <a class="header-anchor" href="#child-process" aria-label="Permalink to &quot;Child Process&quot;">​</a></h3><p><code>child_process</code> module enables spawning child processes. <code>exec()</code> runs shell commands with buffer output. <code>spawn()</code> launches processes with streaming output. <code>fork()</code> creates Node.js child processes with IPC communication. <code>execFile()</code> runs executables without shell.</p><h3 id="worker-threads" tabindex="-1">Worker Threads <a class="header-anchor" href="#worker-threads" aria-label="Permalink to &quot;Worker Threads&quot;">​</a></h3><p><code>worker_threads</code> module enables true parallel execution. Each worker has its own V8 instance, event loop, and memory. <code>Worker</code> class creates threads. <code>postMessage()</code> communicates between threads. <code>SharedArrayBuffer</code> and <code>Atomics</code> enable shared memory.</p><h3 id="es-modules" tabindex="-1">ES Modules <a class="header-anchor" href="#es-modules" aria-label="Permalink to &quot;ES Modules&quot;">​</a></h3><p>ESM is the official module system. <code>.mjs</code> extension or <code>&quot;type&quot;: &quot;module&quot;</code> in <code>package.json</code>. Static <code>import</code>/<code>export</code> enables tree-shaking. <code>import.meta.url</code> provides the module&#39;s URL. Dynamic <code>import()</code> loads modules on demand. Top-level <code>await</code> is supported.</p><h3 id="commonjs" tabindex="-1">CommonJS <a class="header-anchor" href="#commonjs" aria-label="Permalink to &quot;CommonJS&quot;">​</a></h3><p>Legacy module system using <code>require()</code> and <code>module.exports</code>. Synchronous loading. Widely supported but declining in favor of ESM. Many npm packages still use CJS. Interop: ESM can import CJS via default import; CJS cannot <code>require()</code> ESM directly.</p><h3 id="package-management" tabindex="-1">Package Management <a class="header-anchor" href="#package-management" aria-label="Permalink to &quot;Package Management&quot;">​</a></h3><ul><li><strong>npm</strong> — default Node.js package manager; <code>npm install</code>, <code>npm run</code>, <code>npm publish</code></li><li><strong>yarn</strong> — alternatives with workspaces, offline installs; <code>yarn add</code>, <code>yarn workspaces</code></li><li><strong>pnpm</strong> — content-addressable storage, strict dependency resolution; <code>pnpm add</code>, <code>pnpm install</code></li><li>All support monorepo workspaces. Lock files (<code>package-lock.json</code>, <code>yarn.lock</code>, <code>pnpm-lock.yaml</code>) ensure reproducible installs.</li></ul><h3 id="package-json" tabindex="-1">package.json <a class="header-anchor" href="#package-json" aria-label="Permalink to &quot;package.json&quot;">​</a></h3><p>Project manifest: name, version, dependencies, scripts, engines, type. <code>scripts</code> define executable commands. <code>dependencies</code> vs <code>devDependencies</code> separate runtime from build-time. <code>engines</code> specifies Node.js version requirements. <code>type: &quot;module&quot;</code> enables ESM.</p><h3 id="fs-and-path-modules" tabindex="-1">fs and path Modules <a class="header-anchor" href="#fs-and-path-modules" aria-label="Permalink to &quot;fs and path Modules&quot;">​</a></h3><p><code>fs</code> provides file system operations: <code>readFile</code>, <code>writeFile</code>, <code>readdir</code>, <code>stat</code>, <code>mkdir</code>. Async versions (<code>fs/promises</code>) return Promises. <code>path</code> handles cross-platform path operations: <code>path.join()</code>, <code>path.resolve()</code>, <code>path.dirname()</code>, <code>path.extname()</code>. Never construct paths with string concatenation.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Never block the event loop</strong> — offload CPU-intensive work to Worker Threads or child processes; use <code>setImmediate()</code> for breaking up long tasks</li><li><strong>Use streams for large data</strong> — process files and network data with streams; never <code>readFile()</code> entire multi-GB files into memory</li><li><strong>Always handle stream errors</strong> — use <code>pipeline()</code> instead of manual <code>pipe()</code> to ensure proper error handling and cleanup</li><li><strong>Use <code>fs/promises</code> over callback-based <code>fs</code></strong> — Promise-based APIs work with <code>async/await</code> for cleaner code</li><li><strong>Prefer <code>path.join()</code> over string concatenation</strong> — handles platform-specific separators and resolves <code>..</code> correctly</li><li><strong>Use <code>worker_threads</code> for CPU-bound tasks</strong> — image processing, data transformation, and cryptographic operations benefit from true parallelism</li><li><strong>Pin Node.js version in <code>engines</code> field</strong> — specify minimum version: <code>&quot;engines&quot;: { &quot;node&quot;: &quot;&gt;=20.0.0&quot; }</code></li><li><strong>Use environment variables for configuration</strong> — <code>process.env</code> for secrets, feature flags, and deployment-specific values; validate with <code>zod</code> or similar</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>JSON.parse(fs.readFileSync(...))</code> synchronously</strong> — blocks the event loop; use <code>fs.promises.readFile()</code> with <code>JSON.parse()</code> asynchronously</li><li><strong>Storing credentials in code</strong> — never hardcode secrets; use environment variables, <code>.env</code> files (with <code>dotenv</code>), or secret managers</li><li><strong>Ignoring backpressure in streams</strong> — not checking <code>writable.write()</code> return value causes memory exhaustion under load</li><li><strong>Using <code>process.exit()</code> for graceful shutdown</strong> — abrupt exit loses data; use signal handlers (<code>SIGTERM</code>, <code>SIGINT</code>) for cleanup</li><li><strong>Not using <code>--max-old-space-size</code> for memory-heavy apps</strong> — default heap (1.5GB) may be insufficient; tune for your workload</li><li><strong>Using <code>exec()</code> for user input</strong> — <code>exec()</code> runs through shell and is vulnerable to injection; use <code>spawn()</code> with array arguments</li><li><strong>Not separating concerns in <code>package.json</code> scripts</strong> — monolithic scripts are unmaintainable; compose smaller scripts</li><li><strong>Using global variables for state</strong> — Node.js shares global state across requests; use request-scoped state or a database</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Confusing <code>__dirname</code> and <code>__filename</code> in ESM</strong> — these CJS globals do not exist in ESM; use <code>import.meta.dirname</code> (Node.js 21+) or <code>path.dirname(fileURLToPath(import.meta.url))</code></li><li><strong>Forgetting <code>await</code> on async operations</strong> — unawaited Promises fail silently; always <code>await</code> or <code>.catch()</code> async calls</li><li><strong>Not handling uncaught exceptions</strong> — add <code>process.on(&#39;uncaughtException&#39;)</code> and <code>process.on(&#39;unhandledRejection&#39;)</code> handlers for logging</li><li><strong>Using <code>require()</code> in ESM modules</strong> — ESM uses <code>import</code>; <code>require()</code> is not available without <code>createRequire()</code></li><li><strong>Ignoring memory leaks in long-running processes</strong> — event listeners, closures, and global arrays accumulate; monitor with <code>process.memoryUsage()</code></li><li><strong>Not checking file existence before operations</strong> — use <code>fs.access()</code> or <code>fs.stat()</code> with try/catch; never assume files exist</li><li><strong>Using <code>new Buffer()</code></strong> — deprecated since Node.js 6; always use <code>Buffer.from()</code>, <code>Buffer.alloc()</code>, or <code>Buffer.allocUnsafe()</code></li><li><strong>Not respecting <code>NODE_ENV</code></strong> — production environments should disable debug logging, enable caching, and minimize error output</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>CPU-intensive computation</td><td>Worker Threads</td></tr><tr><td>Shell command execution</td><td><code>child_process.execFile()</code> with args array</td></tr><tr><td>File streaming</td><td><code>fs.createReadStream()</code> + <code>pipeline()</code></td></tr><tr><td>Large file processing</td><td>Streams with backpressure handling</td></tr><tr><td>Parallel I/O operations</td><td><code>Promise.all()</code> with async functions</td></tr><tr><td>Shared memory between threads</td><td><code>SharedArrayBuffer</code> + <code>Atomics</code></td></tr><tr><td>IPC between processes</td><td><code>child_process.fork()</code> with <code>send()</code>/<code>on(&#39;message&#39;)</code></td></tr><tr><td>Module system</td><td>ESM for new projects; CJS for legacy compatibility</td></tr><tr><td>Package management</td><td>pnpm for performance and strictness; npm for compatibility</td></tr><tr><td>Path construction</td><td><code>path.join()</code> + <code>path.resolve()</code></td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://nodejs.org/api" target="_blank" rel="noreferrer">Node.js Documentation</a></li><li><a href="https://nodejs.org/en/learn" target="_blank" rel="noreferrer">Node.js Guides</a></li><li><a href="https://docs.libuv.org" target="_blank" rel="noreferrer">libuv Documentation</a></li><li><a href="https://docs.npmjs.com" target="_blank" rel="noreferrer">npm Documentation</a></li><li><a href="https://github.com/goldbergyoni/nodebestpractices" target="_blank" rel="noreferrer">Node.js Best Practices</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li>Node.js 20+ includes built-in test runner (<code>node:test</code>) — no need to install Jest for simple unit tests</li><li><code>--experimental-strip-types</code> (Node.js 22+) enables native TypeScript execution without compilation</li><li><code>node --watch</code> provides file watching and auto-restart without <code>nodemon</code></li><li><code>process.kill(process.pid, &#39;SIGTERM&#39;)</code> triggers graceful shutdown handlers</li><li><code>EventEmitter</code> is the foundation of Node.js async patterns; understanding it is essential for streams, HTTP, and child processes</li><li>Use <code>util.promisify()</code> to convert callback-based functions to Promise-based ones for older APIs</li><li><code>node:sqlite</code> (Node.js 22+) provides built-in SQLite support without external dependencies</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',39)])])}const m=o(s,[["render",d]]);export{h as __pageData,m as default};
